                            .map(({ member }) => formatName(member))
                            .join(", ")
                        : t("unassigned")}
                    </TableCell>
                    <TableCell className="pr-4 text-muted-foreground">
                      {formatDateTime(referral.created_date)}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </FramePanel>
        {!isWidget && data && data.results.length > 0 && !error && (
          <FrameFooter className="flex-row flex-wrap items-center justify-between gap-3">
            <p className="text-xs text-muted-foreground">
              {t("referral_result_range", {
                start: (page - 1) * limit + 1,
                end: Math.min(page * limit, data.count),
                count: data.count,
              })}
            </p>
            <Pagination
              data={{ totalCount: data.count }}
              cPage={page}
              defaultPerPage={limit}
              onChange={setPage}
              className=""
            />
          </FrameFooter>
        )}
        {isWidget && onViewAll && (
          <FrameFooter>
            <Button
              variant="ghost"
              size="sm"
              className="w-full"
              onClick={onViewAll}
            >
              {t("referral_view_all")}
              <ArrowUpRight className="size-4" />
            </Button>
          </FrameFooter>
        )}
      </Frame>
    </section>
  );
}

