    // One URL update keeps clearing multiple filters atomic and preserves context.
    setFilters(patch, { overwrite: false, replace: true });
  };
  const clearFilters = () =>
    handleFilterUpdate({
      status: null,
      assignedToMe: false,
      ...(departmentFilter ? { department: null } : {}),
